        for(int i=1; i<=K; i++){
            for(int j=1; j<=K; j++){
                int a = i;
                int b = j;
                int kou = 0;
                for(int x=0; x<10; x++){
                    int max = Math.max(a, b);
                    int min = Math.min(a, b);
                    if(max%min==0 && x==0){
                        kou = min;
                        break;
                    }
                    a = min;
                    b = max % min;
                    if(a%b==0){
                        kou = b;
                        break;
                    }
                }
                for(int k=1; k<=K; k++){
                    int c = k;
                    int d = kou;
                    for(int x=0; x<10; x++){
                        int max = Math.max(c, d);
