    static class BBuffet {
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            int n = in.nextInt();
            int a[] = ReadInput.readIntArray(n, in);
            int b[] = ReadInput.readIntArray(n, in);
            int c[] = ReadInput.readIntArray(n - 1, in);
            int prev = -1;
            long total = 0;
            for (int i = 0; i < n; i++) {
