		stair[0] = 1;
		for(int i = 0; i < N + 1; i++) {
			if(i < N)stair[i + 1] = (stair[i + 1] + ((ok[i + 1])?stair[i]:0)) % prime;
			if(i < N - 1)stair[i + 2] +=  (stair[i + 2] + ((ok[i + 2])?stair[i]:0)) % prime;
		}

		System.out.println(stair[N]);
	}
}

