    int r[] = new int[Q];
    for (int i = 0; i < Q; i++) {
      l[i] = sc.nextInt();
      r[i] = sc.nextInt();
    }

    for (int i = 0; i < N; i++) {
      if (i > 0) {
        acCount[i] = acCount[i-1];
      }
      if (i >= N-1) {
        break;
      }
      if (S.charAt(i) == 'A' && S.charAt(i+1) == 'C') {
        acCount[i] += 1;
      }
    }
    for (int i = 0; i < Q; i++) {
      int ans = acCount[r[i]-1] - acCount[l[i]-1] + 1;
      if (l[i]-1 > 0) {
