public class Main {
  private static boolean solve(char[] cs) {
    int[] counts = new int[26];
    for (char c : cs) {
      counts[c - 'a']++;
    }
    for (int count : counts) {
      if (count % 2 == 1) {
        return false;
      }
    }
    return true;
  }

  private static void execute(ContestReader reader, PrintWriter out) {
    char[] cs = reader.nextCharArray();
    out.println(solve(cs) ? "Yes" : "No");
  }

